class Steps {
  // (a) sumTo(int n) -> int

  // (b) countEvens(int n) -> int

  // (c) verdict(int score) -> String

  // (d) firstMultiple(int start, int step) -> int
}

2.1.reference:
class Steps {
  public static int sumTo(int n) {
    int total = 0;
    for (int i = 1; i <= n; i++) {
      total = total + i;
    }
    return total;
  }

  public static int countEvens(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
      if (i % 2 == 0) {
        count = count + 1;
      }
    }
    return count;
  }

  public static String verdict(int score) {
    if (score >= 60) {
      return "PASS";
    }
    return "FAIL";
  }

  public static int firstMultiple(int start, int step) {
    int value = 0;
    while (value < start) {
      value = value + step;
    }
    return value;
  }
}

