2.7.reference:
class Digits {
  public static int count(int n) {
    int digits = 0;
    while (n > 0) {
      digits = digits + 1;
      n = n / 10;
    }
    if (digits == 0) {
      return 1;
    }
    return digits;
  }

  public static int sum(int n) {
    int total = 0;
    while (n > 0) {
      total = total + n % 10;
      n = n / 10;
    }
    return total;
  }

  public static int lastDigit(int n) {
    return n % 10;
  }

  public static int reverse(int n) {
    int out = 0;
    while (n > 0) {
      out = out * 10 + n % 10;
      n = n / 10;
    }
    return out;
  }
}

