2.9.reference:
class Stats {
  public static int betterMax(int running, int next) {
    if (next > running) {
      return next;
    }
    return running;
  }

  public static int rangeSum(int low, int high, int skip) {
    int total = 0;
    for (int i = low; i <= high; i++) {
      if (i % skip != 0) {
        total = total + i;
      }
    }
    return total;
  }

  public static int countAbove(int low, int high, int threshold) {
    int count = 0;
    for (int i = low; i <= high; i++) {
      if (i > threshold) {
        count = count + 1;
      }
    }
    return count;
  }

  public static int firstAbove(int low, int high, int threshold) {
    for (int i = low; i <= high; i++) {
      if (i > threshold) {
        return i;
      }
    }
    return high + 1;
  }
}

2.10.starter:
class Scan {
  // (a) countChar(String s, String target) -> int

  // (b) reverse(String s) -> String

  // (c) isPalindrome(String s) -> boolean

  // (d) countVowels(String s) -> int
}

2.10.reference:
class Scan {
  public static int countChar(String s, String target) {
    char want = target.charAt(0);
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
      if (s.charAt(i) == want) {
        count = count + 1;
      }
    }
    return count;
  }

  public static String reverse(String s) {
    String out = "";
    for (int i = s.length() - 1; i >= 0; i--) {
      out = out + s.charAt(i);
    }
    return out;
  }

  public static boolean isPalindrome(String s) {
    return s.equals(reverse(s));
  }

  public static int countVowels(String s) {
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
      char c = s.charAt(i);
      if (c == 97 || c == 101 || c == 105 || c == 111 || c == 117) {
        count = count + 1;
      }
    }
    return count;
  }
}

