  // (d) rowLabel(int row, int cols) -> String
}

2.11.reference:
class Grid {
  public static int cells(int rows, int cols) {
    int count = 0;
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        count = count + 1;
      }
    }
    return count;
  }

  public static int sumProducts(int rows, int cols) {
    int total = 0;
    for (int r = 1; r <= rows; r++) {
      for (int c = 1; c <= cols; c++) {
        total = total + r * c;
      }
    }
    return total;
  }

  public static int countPairs(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
      for (int j = i + 1; j <= n; j++) {
        count = count + 1;
      }
    }
    return count;
  }

  public static String rowLabel(int row, int cols) {
    String out = "";
    for (int c = 1; c <= cols; c++) {
      if (c > 1) {
        out = out + " ";
      }
      out = out + row * c;
    }
    return out;
  }
}

2.12.starter:
class Work {
  // (a) singleLoop(int n) -> int

  // (b) nestedLoop(int n) -> int

  // (c) triangleLoop(int n) -> int

  // (d) halvingLoop(int n) -> int
}

2.12.reference:
class Work {
  public static int singleLoop(int n) {
    int steps = 0;
    for (int i = 0; i < n; i++) {
      steps = steps + 1;
    }
    return steps;
  }

  public static int nestedLoop(int n) {
    int steps = 0;
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        steps = steps + 1;
      }
    }
    return steps;
  }

  public static int triangleLoop(int n) {
    int steps = 0;
    for (int i = 0; i < n; i++) {
      for (int j = i + 1; j < n; j++) {
        steps = steps + 1;
      }
    }
    return steps;
  }

  public static int halvingLoop(int n) {
    int steps = 0;
    int value = n;
    while (value > 0) {
      steps = steps + 1;
      value = value / 2;
    }
    return steps;
  }
}

