  // (b) min(int[] data) -> int

  // (c) range(int[] data) -> int

  // (d) mean(int[] data) -> int
}

4.2.reference:
class Summary {
  public static int max(int[] data) {
    int best = data[0];
    for (int i = 1; i < data.length; i++) {
      if (data[i] > best) {
        best = data[i];
      }
    }
    return best;
  }

  public static int min(int[] data) {
    int best = data[0];
    for (int i = 1; i < data.length; i++) {
      if (data[i] < best) {
        best = data[i];
      }
    }
    return best;
  }

  public static int range(int[] data) {
    return max(data) - min(data);
  }

