}

4.14.reference:
class Searcher {
  public static int linear(int[] data, int target) {
    for (int i = 0; i < data.length; i++) {
      if (data[i] == target) {
        return i;
      }
    }
    return -1;
  }

  public static int binary(int[] data, int target) {
    int low = 0;
    int high = data.length - 1;
    while (low <= high) {
      int mid = (low + high) / 2;
      if (data[mid] == target) {
        return mid;
      }
      if (data[mid] < target) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    return -1;
  }

  public static int binarySteps(int[] data, int target) {
    int low = 0;
    int high = data.length - 1;
    int steps = 0;
    while (low <= high) {
      steps = steps + 1;
      int mid = (low + high) / 2;
      if (data[mid] == target) {
        return steps;
      }
      if (data[mid] < target) {
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }
    return steps;
  }

  public static boolean contains(int[] data, int target) {
    return binary(data, target) >= 0;
  }
}

