4.17.reference:
class RecSearch {
  public static int find(int[] data, int target, int low, int high) {
    if (low > high) {
      return -1;
    }
    int mid = (low + high) / 2;
    if (data[mid] == target) {
      return mid;
    }
    if (data[mid] < target) {
      return find(data, target, mid + 1, high);
    }
    return find(data, target, low, mid - 1);
  }

  public static int find(int[] data, int target) {
    return find(data, target, 0, data.length - 1);
  }

  public static int maxFrom(int[] data, int i) {
    if (i == data.length - 1) {
      return data[i];
    }
    int rest = maxFrom(data, i + 1);
    if (data[i] > rest) {
      return data[i];
    }
    return rest;
  }

  public static int countFrom(int[] data, int target, int i) {
    if (i >= data.length) {
      return 0;
    }
    int rest = countFrom(data, target, i + 1);
    if (data[i] == target) {
      return 1 + rest;
    }
    return rest;
  }
}
